'use strict';
const root=document.querySelector('main'),role=document.querySelector('#role'),state=document.querySelector('#state');let bookingStatus='PENDING',jobStatus='READY',pageNo=1,filter='all';
let selection={name:'Cordless drill',daily:2500,deposit:10000,qty:1,days:2,start:'2026-11-02T08:00',end:'2026-11-04T08:00'}; const euros=n=>'€'+(n/100).toFixed(2); const rental=()=>selection.daily*selection.days*selection.qty, deposit=()=>selection.deposit*selection.qty, auth=()=>rental()+deposit();
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(s,to,cls='primary')=>`<a class="button ${cls}" href="#${to}">${s}</a>`;
const badge=(s,type='')=>`<span class="badge ${type}">${s}</span>`;
const alert=(s,type='')=>`<div class="alert ${type}" role="status" aria-live="polite">${s}</div>`;
const table=(headers,rows)=>`<div class="table-scroll" tabindex="0" aria-label="Таблица, прокручивается"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const formError='<p id="form-error" class="errors" role="alert"></p>';
const art=`<svg viewBox="0 0 240 140" role="img" aria-label="Иллюстрация строительного инструмента"><rect x="28" y="39" width="116" height="42" rx="13" fill="#075d64"/><rect x="136" y="47" width="50" height="26" rx="3" fill="#516977"/><path d="M81 77h31l-8 39H69z" fill="#263f4e"/><rect x="64" y="112" width="49" height="15" rx="4" fill="#075d64"/><path d="M185 56h32v8h-32" fill="#9aadb6"/><rect x="35" y="50" width="25" height="7" rx="2" fill="#b6d4d5"/></svg>`;
const settledDemo=()=>Math.min(auth(),rental()+selection.daily*selection.qty+1000);
function summary(){return `<section class="panel summary"><span class="eyebrow">Неизменяемая котировка / DEMO</span><h2>${escapeHtml(selection.name)}</h2><p>Tallinn · UTC ${escapeHtml(selection.start)} → ${escapeHtml(selection.end)}<br>${selection.qty} экземпляр(а) · ${selection.days} × 24h</p><div class="row"><span>Аренда</span><strong>${euros(rental())}</strong></div><div class="row"><span>Возвратный депозит</span><strong>${euros(deposit())}</strong></div><div class="row"><span>Авторизация</span><strong>${euros(auth())}</strong></div><small>Средства списываются после возврата. В этой демонстрации реальных платежей нет.</small></section>`}
function timeline(){const cancelled=['CANCELLING','CANCELLED'].includes(bookingStatus);return `<ol class="timeline"><li>Котировка сохранена<small>Demo price snapshot ${euros(rental())} + депозит ${euros(deposit())}</small></li><li>Запрос Inventory записан<small>Временный hold / deadline10min</small></li><li class="${bookingStatus==='PENDING'?'pending':''}">${cancelled?'Запрошена компенсация / release + void':bookingStatus==='PENDING'?'Авторизация PSP ожидается':'Авторизация PSP получена'}<small>Stable provider key; unknown outcome never treated as decline</small></li><li class="${['PENDING','CANCELLING'].includes(bookingStatus)?'pending':''}">${bookingStatus==='CANCELLED'?'Компенсации подтверждены, allocation released':bookingStatus==='CANCELLING'?'CANCELLING: ожидаются доказательства':bookingStatus==='PENDING'?'Allocation ещё не подтверждена':'Allocation committed / физический workflow'}<small>Authoritative business state required in implementation</small></li></ol>`}
function pageContent(id){switch(id){
case 'login':return `<div class="cols"><section class="panel"><h2>Добро пожаловать</h2><p>Ваш доступ принадлежит Demo Org A. В будущем приложении вход через OIDC.</p><label>Email<input type="email" placeholder="alice@example.invalid" autocomplete="email"></label><div class="actions">${btn('Продолжить (демо)','catalog')}</div></section>${summary()}</div>`;
case 'catalog':return `<div class="filters"><label>Поиск модели<input id="model-search" placeholder="Название оборудования"></label><label>Категория<select id="category"><option value="all">Все категории</option><option value="tools">Инструмент</option><option value="power">Электропитание</option></select></label><label>Склад<select><option>Tallinn</option><option>Tartu</option></select></label></div><div id="model-results">${models('')}</div><div class="actions"><button id="prev-page">← Назад</button><span id="page-label">Страница ${pageNo} из 2</span><button id="next-page">Вперёд →</button></div>`;
case 'availability':return `<div class="cols"><section class="panel"><h2>Наличие на период</h2><p>Предварительная доступность не гарантирует резерв.</p><form id="availability-form"><label>Начало (UTC)<input id="start" type="datetime-local" value="${selection.start}" required aria-describedby="form-error"></label><label>Конец (UTC)<input id="end" type="datetime-local" value="${selection.end}" required aria-describedby="form-error"></label><label>Количество<input id="qty" type="number" value="${selection.qty}" min="1" max="5" required aria-describedby="form-error"></label>${formError}<button class="primary" type="submit">Получить котировку</button></form><p>${badge('1 доступный экземпляр')} <small>Обновлено по данным Inventory / DEMO</small></p></section>${summary()}</div>`;
case 'quote':return `<div class="cols"><section class="panel"><h2>Ваша цена зафиксирована</h2>${badge('Quote ACTIVE')}<p>Котировка действует 15 минут. Если она истечёт, подтвердите новую цену перед арендой.</p><div class="row"><span>Тариф / 24h</span><strong>${euros(selection.daily)}</strong></div><div class="row"><span>Длительность</span><strong>${selection.days} × 24h (rounded up)</strong></div><div class="row"><span>Rate version</span><code>v3</code></div><div class="actions">${btn('Перейти к аренде','checkout')}${btn('Изменить срок','availability','')}</div></section>${summary()}</div>`;
case 'checkout':return `<div class="cols"><section class="panel"><h2>Проверьте аренду</h2><p>Мы удержим экземпляр на 10 минут, запросим авторизацию и подтвердим выделение. Потерянный ответ не требует повторной оплаты.</p><form id="checkout-form"><label>Контактное имя<input required value="Alice Demo" autocomplete="name"></label><label class="inline-check"><input type="checkbox" id="consent" required> Я проверил срок и учебную сумму</label>${formError}<button type="submit" class="primary wide">Начать резерв · ${euros(auth())} авторизация</button></form></section>${summary()}</div>`;
case 'pending':return `<div class="cols"><section class="panel"><h2>Ожидаем подтверждение</h2>${badge('PENDING','warn')}<p>Аренда ещё не подтверждена. Не создавайте повторный checkout, чтобы узнать статус.</p>${timeline()}<code>correlation: demo-corr-1042</code><div class="actions"><button id="advance" class="primary">Симулировать успешную авторизацию + commit</button>${btn('Запросить отмену','cancel','')}</div></section>${summary()}</div>`;
case 'booking':return `<div class="subhead"><div>${badge(bookingStatus,bookingStatus==='PENDING'?'warn':'')}<p>DF-1042 · Tallinn · Обновлено только в демонстрации</p></div>${btn('Отменить до выдачи','cancel','')}</div><div class="cols"><section class="panel"><h2>История аренды</h2>${timeline()}<div class="row"><span>Экземпляр</span><code>DRILL-TLL-001</code></div><div class="actions">${btn('Открыть расчёты','billing','')}${btn('Перейти к выдаче','handover','')}</div></section>${summary()}</div>`;
case 'cancel':return `<section class="panel"><h2>Подтверждение отмены</h2>${alert('После handover claim отмена запрещена. Возврат депозита может ожидать компенсации зависимостей.','warn')}<form id="cancel-form"><label>Причина<textarea id="reason" required minlength="3" maxlength="1000" aria-describedby="form-error" placeholder="Опишите причину"></textarea></label>${formError}<div class="actions"><button class="danger" type="submit">Запросить отмену</button>${btn('Оставить аренду','booking','')}</div></form></section>`;
case 'notifications':return `<section class="panel"><h2>Изменения ваших аренд</h2><div class="row"><div><strong>DF-1042: статус обновлён</strong><p>Подтверждение Inventory и Billing получено.</p></div>${btn('Открыть','booking','')}</div><div class="row"><div><strong>Возврат DF-1038 принят</strong><p>Расчёт в процессе. Повторная аренда не нужна.</p></div><button id="mark-read">Отметить прочитанным</button></div><form id="preference-form"><label class="inline-check"><input type="checkbox" checked id="email"> Email уведомления</label><button type="submit" class="wide">Сохранить предпочтение (демо)</button></form></section>`;
case 'warehouse':return `<div class="stat-grid"><section class="panel"><span class="muted">На выдачу</span><div class="count">1</div></section><section class="panel"><span class="muted">В аренде</span><div class="count">1</div></section><section class="panel"><span class="muted">Quarantine</span><div class="count">1</div></section></div><section class="panel" style="margin-top:24px"><h2>Задания Tallinn</h2>${table(['Job','Аренда','Статус','Оборудование','Действие'],[['JOB-1042','DF-1042',badge(jobStatus),'DRILL-TLL-001',btn('Выдать','handover','')],['JOB-1038','DF-1038',badge('IN_USE','warn'),'DRILL-TLL-005',btn('Принять','return','')]])}</section>`;
case 'handover':return `<div class="cols"><section class="panel"><h2>Осмотр перед выдачей</h2><p>Сначала Booking атомарно фиксирует claim. Отмена после claim невозможна; нельзя автоматически снять claim по таймеру.</p><form id="handover-form"><div class="row"><strong>DRILL-TLL-001</strong>${badge('READY')}</div><label class="inline-check"><input id="serial" type="checkbox" required> Серийный номер и состояние сверены</label><label class="inline-check" style="margin-top:16px"><input id="physical" type="checkbox" required> Готов передать оборудование</label>${formError}<button type="submit" class="primary wide">Claim и запись выдачи (демо)</button></form></section>${summary()}</div>`;
case 'return':return `<div class="cols"><section class="panel"><h2>Акт возврата</h2><form id="return-form"><label>Состояние<select id="condition"><option value="good">Исправно</option><option value="damaged">Повреждено — quarantine</option></select></label><label>Ущерб в minor units (100 = €1)<input id="damage" type="number" value="0" min="0" max="10000" required aria-describedby="form-error"></label><label>Заметки<textarea id="notes" maxlength="1000"></textarea></label><label class="inline-check"><input id="all-assets" type="checkbox" required> Все экземпляры возвращены</label>${formError}<button class="primary wide" type="submit">Сохранить акт (демо)</button></form></section><section class="panel summary"><h2>Расчёт после возврата</h2><p>Rental €50 + late fee + damage. Capture не превышает €150. Превышение отправляется в manual review.</p>${badge('SETTLEMENT PENDING','warn')}<p>Повреждённый asset недоступен для следующей выдачи до ремонта.</p></section></div>`;
case 'fleet':return `<section class="panel"><h2>Экземпляры / Tallinn</h2>${table(['Serial','Model','State','Version',''],[['DRILL-TLL-001','Cordless drill',badge('READY'),'v3',btn('Ремонт','maintenance','')],['DRILL-TLL-005','Cordless drill',badge('RENTED','warn'),'v8','DF-1038'],['GEN-TLL-009','Generator',badge('QUARANTINED','bad'),'v5',btn('Ремонт','maintenance','')]])}<small>If-Match обязателен. Устаревшая форма получает412 и предложение обновить.</small></section>`;
case 'maintenance':return `<section class="panel"><h2>Блокировка на ремонт</h2><form id="maintenance-form"><label>Экземпляр<input value="GEN-TLL-009" readonly></label><label>Причина<textarea required minlength="3" maxlength="1000"></textarea></label><label>Начало<input type="datetime-local" value="2026-11-02T08:00" required></label><label>Конец<input type="datetime-local" value="2026-11-03T08:00" required></label>${formError}<div class="actions"><button type="submit" class="primary">Создать maintenance allocation</button><button type="button" id="repair">Завершить ремонт (демо)</button></div></form><p>Пересекающийся committed booking вызывает409. Никакого скрытого удаления аренды.</p></section>`;
case 'billing':return `<div class="cols"><section class="panel"><h2>Payment intent / DF-1042</h2>${table(['Operation','Amount','State'],[['Authorize',euros(auth()),badge('AUTHORIZED')],['Capture',euros(settledDemo()),badge('CAPTURED')],['Void remainder',euros(auth()-settledDemo()),badge('VOIDED')]])}<p>Пример с rental ${euros(rental())} + late ${euros(selection.daily*selection.qty)} + damage €10.</p><div class="actions">${btn('Возврат средств','refund')}${btn('Разобрать UNKNOWN','operations','')}</div><h3 style="margin-top:28px">Ledger — immutable history</h3><code>AUTH ${auth()} / CAPTURE ${settledDemo()} / VOID ${auth()-settledDemo()}</code></section>${summary()}</div>`;
case 'refund':return `<section class="panel"><h2>Возврат списанной суммы</h2><p>Доступно к возврату ${euros(settledDemo())}. Pending refund резервирует сумму от конкурентных операций.</p><form id="refund-form"><label>Сумма в minor units<input id="refund-amount" type="number" min="1" max="${settledDemo()}" value="1000" required aria-describedby="form-error"></label><label>Причина<textarea required minlength="3" maxlength="1000" aria-describedby="form-error"></textarea></label>${formError}<button type="submit" class="primary">Запросить refund (демо)</button></form></section>`;
case 'team':return `<section class="panel"><h2>Участники Demo Org A</h2>${table(['Subject','Role','Depot','Status'],[['alice-demo','customer','—',badge('active')],['operator-tll','operator','Tallinn',badge('active')],['finance-demo','finance','—',badge('active')]])}<form id="team-form" style="margin-top:24px"><label>Subject ID<input required value="new-demo"></label><label>Роль<select><option>customer</option><option>operator</option><option>finance</option><option>org_admin</option></select></label><label>Depot (operator only)<select><option>Tallinn</option><option>Tartu</option></select></label><button type="submit" class="primary">Назначить membership (демо)</button></form></section>`;
case 'rate':return `<section class="panel"><h2>Новый тариф · Cordless drill</h2><p>Текущие quotes не пересчитываются. Rate v3 = €25 / deposit €100.</p><form id="rate-form"><label>Daily minor units<input type="number" min="1" value="3000" required></label><label>Deposit minor units<input type="number" min="0" value="10000" required></label><label>Действует с (UTC)<input type="datetime-local" value="2026-11-03T08:00" required></label><button type="submit" class="primary">Создать новую version (демо)</button></form></section>`;
case 'audit':return `<section class="panel"><h2>Audit события</h2>${table(['UTC','Actor','Action','Target','Correlation'],[['08:00','alice-demo','booking.requested','DF-1042','demo-corr-1042'],['08:01','billing service','payment.authorized','INT-1042','demo-corr-1042'],['08:02','operator-tll','handover.claim','JOB-1042','demo-corr-1042']])}<p>JWT, email и секреты не попадают в audit/logs.</p></section>`;
case 'operations':return `<section class="panel"><h2>Incident INC-DEMO-07</h2>${badge('PAYMENT UNKNOWN','warn')}<p>Provider мог авторизовать сумму, но ответ потерян. Нельзя повторить запрос с новым ключом.</p><div class="row"><span>Provider key</span><code>DF-1042:authorize:v1</code></div><div class="row"><span>Hold deadline</span><code>08:10 UTC</code></div><div class="row"><span>Требуемое действие</span><strong>Query same key → commit или void</strong></div><div class="actions"><button id="reconcile" class="primary">Симулировать reconcile</button><a class="button" href="../atlas/index.html#doc/operations%2Frunbooks%2Fpayment-unknown.md">Runbook</a></div></section>`;
case 'denied':return `<section class="panel">${alert('403 · Для операции нужна роль и назначение depot. Данные чужой организации скрыты.','error')}<div class="actions">${btn('Войти','login')}${btn('Вернуться в каталог','catalog','')}</div></section>`;
case 'contracts':return `<section class="panel"><h2>Contract review reference</h2><p>Этот экран — инструмент атласа, не обязательная страница бизнес-продукта.</p><p>OpenAPI / AsyncAPI v1. Required field changes require v2 and old consumer proof.</p><a href="../atlas/index.html#data">Перейти к данным и событиям →</a></section>`;
default:return alert('Экран не найден','error');}}
function models(q){let all=[['Cordless drill','tools','€25 / day'],['Portable generator','power','€60 / day'],['Impact driver','tools','€20 / day']];let found=all.filter(x=>(filter==='all'||x[1]===filter)&&x[0].toLowerCase().includes(q.toLowerCase()));found=found.slice((pageNo-1)*2,pageNo*2);return found.length?`<div class="cards">${found.map(([name,cat,price])=>`<article class="model"><div class="product-art">${art}</div><div class="model-content"><span class="eyebrow">${cat} / DEMO</span><h2>${name}</h2><p>${price} · refundable deposit</p>${badge('Наличие зависит от срока')}<div class="actions"><a class="button primary" data-model="${name}" href="#availability">Выбрать период</a></div></div></article>`).join('')}</div>`:alert('Нет моделей по выбранным фильтрам. Измените запрос.')}
function show(){let id=location.hash.slice(1)||'catalog',s=window.SCREENS.find(s=>s.id===id);if(!s)s=window.SCREENS[1];if(['warehouse','handover','return','fleet','maintenance','operations'].includes(id))role.value='operator';else if(['billing','refund'].includes(id))role.value='finance';else if(['team','rate','audit','contracts'].includes(id))role.value='org_admin';else role.value='customer';document.querySelector('#routes').innerHTML=window.SCREENS.filter(x=>x.role===role.value&&x.id!=='denied').map(x=>`<a href="#${x.id}" class="${x.id===id?'active':''}">${x.title}</a>`).join('');document.querySelector('#mapping').textContent=`${s.requirements.join(' / ')} · ${s.milestone} · ${id}`;
let body=`<span class="eyebrow">${role.options[role.selectedIndex].text} / Demo Org A</span><h1>${s.title}</h1>`;
if(state.value==='loading')body+=`<section class="panel" role="status" aria-label="Загрузка">Загрузка данных…<div class="loading"></div><div class="loading short"></div><div class="loading"></div></section>`;
else if(state.value==='empty')body+=`<section class="panel"><h2>Пока нет записей</h2><p>Нет данных по текущим фильтрам или периоду.</p><button id="reset-state">Очистить фильтры / обновить</button></section>`;
else if(state.value==='denied')body+=pageContent('denied');
else {if(state.value==='error')body+=alert('dependency_unavailable · Результат операции может быть неизвестен. Проверьте статус по прежнему operation ID. Correlation demo-1042.','error');if(state.value==='reconnecting')body+=alert('Соединение SSE потеряно. Показан последний snapshot; выполняется восстановление по cursor.','warn');if(state.value==='success')body+=alert('Демонстрационное действие завершено. В реализации показывать только authoritative state.');body+=pageContent(id)}
root.innerHTML=body;wire();}
function feedback(message,type=''){let e=document.querySelector('#feedback');if(!e){e=document.createElement('div');e.id='feedback';root.prepend(e)}e.innerHTML=alert(message,type)}
function wire(){const on=(id,event,fn)=>{const e=document.getElementById(id);if(e)e.addEventListener(event,fn)};on('model-search','input',e=>document.querySelector('#model-results').innerHTML=models(e.target.value));on('category','change',e=>{filter=e.target.value;pageNo=1;document.querySelector('#model-results').innerHTML=models(document.querySelector('#model-search').value)});on('next-page','click',()=>{pageNo=2;show()});on('prev-page','click',()=>{pageNo=1;show()});on('reset-state','click',()=>{state.value='normal';filter='all';pageNo=1;show()});
on('availability-form','submit',e=>{e.preventDefault();const a=Date.parse(document.querySelector('#start').value+'Z'),b=Date.parse(document.querySelector('#end').value+'Z'),qty=Number(document.querySelector('#qty').value);if(!(b>a)||b-a<3600000||b-a>30*86400000||qty<1||qty>5){document.querySelector('#form-error').textContent='Период 1h..30d; конец позже начала; количество1..5.';return}selection={...selection,start:document.querySelector('#start').value,end:document.querySelector('#end').value,qty,days:Math.ceil((b-a)/86400000)};location.hash='quote'});
on('checkout-form','submit',e=>{e.preventDefault();bookingStatus='PENDING';location.hash='pending'});on('advance','click',()=>{bookingStatus='CONFIRMED';location.hash='booking'});
on('cancel-form','submit',e=>{e.preventDefault();if(jobStatus==='IN_USE'){feedback('409 cannot_cancel: handover claim уже принят.','error');return}bookingStatus='CANCELLING';feedback('CANCELLING: запрос записан. Release и void ещё ожидаются.','warn');let button=document.createElement('button');button.textContent='Симулировать release + full void';button.className='primary';button.onclick=()=>{bookingStatus='CANCELLED';location.hash='booking'};root.querySelector('#feedback').append(button)});
on('handover-form','submit',e=>{e.preventDefault();if(bookingStatus!=='CONFIRMED'){feedback('409: аренда не CONFIRMED. Сначала пройдите customer checkout и симуляцию commit.','error');return}jobStatus='IN_USE';bookingStatus='IN_USE';feedback('Handover claim и физический акт записаны (демо). Отмена теперь запрещена.');});
on('return-form','submit',e=>{e.preventDefault();if(jobStatus!=='IN_USE'){feedback('409: выдача ещё не записана.','error');return}if(document.querySelector('#condition').value==='damaged'&&!document.querySelector('#notes').value.trim()){document.querySelector('#form-error').textContent='Для повреждения требуется заметка.';return}jobStatus='RETURNED';bookingStatus='SETTLING';feedback('Акт принят. Settlement pending; damaged asset отправляется в quarantine.','warn')});
on('refund-form','submit',e=>{e.preventDefault();feedback('REFUND_PENDING: сумма зарезервирована; ожидается ответ sandbox PSP.','warn')});on('repair','click',()=>feedback('Осмотр ремонта записан; asset READY (демо).'));on('reconcile','click',()=>feedback('Reconcile demo: authorized, hold expired → запрос full void; результат не CONFIRMED.','warn'));on('mark-read','click',e=>{e.target.textContent='Прочитано';e.target.disabled=true});
['preference-form','team-form','rate-form','maintenance-form'].forEach(id=>on(id,'submit',e=>{e.preventDefault();feedback('Демонстрационное изменение сохранено на этом экране. Backend отсутствует.')}));}
role.onchange=()=>{state.value='normal';location.hash={customer:'catalog',operator:'warehouse',finance:'billing',org_admin:'team'}[role.value]};state.onchange=show;window.addEventListener('hashchange',()=>{show();root.focus();window.scrollTo(0,0)});show();

root.addEventListener('click',e=>{const a=e.target.closest('[data-model]');if(a){const n=a.dataset.model;selection={...selection,name:n,daily:n==='Portable generator'?6000:n==='Impact driver'?2000:2500,deposit:n==='Portable generator'?20000:10000};}});
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();root.focus();root.scrollIntoView({block:'start'});});
